export interface CircuitLookup {
  round?: number | string | null;
  circuitKey?: number | string | null;
  country?: string | null;
  location?: string | null;
  name?: string | null;
}

/**
 * Find canonical circuit geometry for a given round, country, location, or name.
 */
export function getCircuitGeometry(lookup?: CircuitLookup | null): CircuitGeometry | null {
  if (!lookup) return null;

  // 1. By Round number
  if (lookup.round !== undefined && lookup.round !== null && lookup.round !== '') {
    const rNum = typeof lookup.round === 'string' ? parseInt(lookup.round, 10) : lookup.round;
    if (!isNaN(rNum)) {
      const match = CANONICAL_CIRCUITS.find(c => c.round === rNum);
      if (match) return match;
    }
  }

  // 2. By Circuit Key
  if (lookup.circuitKey !== undefined && lookup.circuitKey !== null && lookup.circuitKey !== '') {
    const kNum = typeof lookup.circuitKey === 'string' ? parseInt(lookup.circuitKey, 10) : lookup.circuitKey;
    if (!isNaN(kNum)) {
      const match = CANONICAL_CIRCUITS.find(c => c.circuitKey === kNum);
      if (match) return match;
    }
  }

  // 3. By Country or Location or Name
  const loc = (lookup.location || '').toLowerCase().trim();
  const cty = (lookup.country || '').toLowerCase().trim();
  const nm = (lookup.name || '').toLowerCase().trim();

  if (loc || cty || nm) {
    for (const c of CANONICAL_CIRCUITS) {
      const cLoc = c.location.toLowerCase();
      const cCty = c.country.toLowerCase();
      const cNm = c.name.toLowerCase();

      if (loc && (cLoc.includes(loc) || loc.includes(cLoc))) return c;
      if (cty && (cCty.includes(cty) || cty.includes(cCty))) return c;
      if (nm && (cNm.includes(nm) || nm.includes(cNm))) return c;
    }
  }

  return null;
}

/**
 * Sample (x, y) along the circuit path for a normalized distance in [0.0, 1.0].
 * Uses high-density point interpolation along normalized arc length.
 */
export function sampleCircuitPosition(
  geom: CircuitGeometry,
  normDist: number,
  pathElem?: SVGPathElement | null
): { x: number; y: number } {
  const t = Math.max(0, Math.min(1, isNaN(normDist) ? 0 : normDist));

  // Fast DOM SVG path sampling if path element is provided and supported
  if (pathElem && typeof pathElem.getTotalLength === 'function') {
    try {
      const totalLen = pathElem.getTotalLength();
      if (totalLen > 0) {
        const pt = pathElem.getPointAtLength(t * totalLen);
        if (pt && !isNaN(pt.x) && !isNaN(pt.y)) {
          return { x: pt.x, y: pt.y };
        }
      }
    } catch {
      // Fallback to interpolation
    }
  }

  const pts = geom.points;
  if (!pts || pts.length === 0) return { x: 0, y: 0 };
  if (pts.length === 1) return { x: pts[0].x, y: pts[0].y };

  // Binary search along normalized distance
  let low = 0;
  let high = pts.length - 1;

  while (low <= high) {
    const mid = (low + high) >> 1;
    if (pts[mid].d < t) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  const i0 = Math.max(0, Math.min(pts.length - 1, low - 1));
  const i1 = Math.min(pts.length - 1, low);

  if (i0 === i1) return { x: pts[i0].x, y: pts[i0].y };

  const p0 = pts[i0];
  const p1 = pts[i1];
  const span = p1.d - p0.d;
  const frac = span > 0 ? (t - p0.d) / span : 0;

  return {
    x: p0.x + (p1.x - p0.x) * frac,
    y: p0.y + (p1.y - p0.y) * frac,
  };
}

/**
 * Build SVG path string from canonical circuit points.
 */
export function getCircuitSvgPath(geom: CircuitGeometry, flipY?: (y: number) => number): string {
  const pts = geom.points;
  if (!pts || pts.length === 0) return "";
  return pts.map((p, i) => (i === 0 ? "M " : "L ") + p.x.toFixed(2) + " " + (flipY ? flipY(p.y).toFixed(2) : p.y.toFixed(2))).join(" ") + " Z";
}
